<style>
  body {
    font-family: "SimSun", "Songti SC", serif;
    margin: 0;
    padding: 0;
    background: #eee;
  }
  .page {
    width: 900px;
    margin: 20px auto;
    background: #fff;
    padding: 15px 20px;
    box-sizing: border-box;
  }
  /* Header */
  .masthead {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    border-bottom: 3px solid #000;
    padding-bottom: 6px;
    margin-bottom: 4px;
  }
  .page-num-block {
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .page-num {
    font-size: 30px;
    font-weight: bold;
    color: #000;
    font-family: "Arial", sans-serif;
  }
  .page-title {
    font-size: 22px;
    font-weight: bold;
    letter-spacing: 2px;
  }
  .masthead-title {
    font-size: 30px;
    font-weight: bold;
    letter-spacing: 4px;
    flex: 1;
    text-align: center;
  }
  .masthead-title .oversea {
    font-size: 12px;
    color: #b00;
    font-weight: normal;
    vertical-align: top;
  }
  .masthead-info {
    font-size: 10px;
    text-align: right;
    line-height: 1.5;
    white-space: nowrap;
  }
  .thin-red-line {
    height: 2px;
    background: #b00;
    margin-bottom: 10px;
  }

  /* Columns layout */
  .columns-6 {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    column-gap: 12px;
    border-top: none;
  }
  .col {
    font-size: 10.3px;
    line-height: 1.55;
    text-align: justify;
    border-right: 1px solid #ccc;
    padding-right: 8px;
  }
  .col:last-child {
    border-right: none;
    padding-right: 0;
  }
  .continued {
    font-size: 10px;
    color: #333;
    margin-bottom: 4px;
  }
  .headline {
    font-size: 13.5px;
    font-weight: bold;
    text-align: center;
    line-height: 1.4;
    margin: 4px 0 8px 0;
  }
  .subhead-num {
    font-weight: bold;
  }
  p {
    margin: 0 0 6px 0;
    text-indent: 1em;
  }
